syntax = "proto3";

package risk.v1;

// The contract: field numbers, not names, go on the wire, so never reuse or renumber them.
service RiskScorer {
  rpc Score (Transaction) returns (Prediction);
  rpc ScoreBatch (TransactionBatch) returns (PredictionBatch);
}

message Transaction {
  double amount = 1;
  int32 hour = 2;
  string channel = 3;
  int32 account_age_days = 4;
  int32 tx_last_24h = 5;
  double distance_km = 6;
}

message Prediction {
  double score = 1;
  string decision = 2;
  string model_version = 3;
}

message TransactionBatch {
  repeated Transaction transactions = 1;
}

message PredictionBatch {
  repeated Prediction predictions = 1;
  string model_version = 2;
}

"""A gRPC model service: typed messages, input checks mapped to status codes, and the ONNX model.
Generate the stubs first: python -m grpc_tools.protoc -I. --python_out=. --grpc_python_out=. risk.proto"""
from concurrent import futures

import grpc

import risk_pb2
import risk_pb2_grpc
from onnx_model import CHANNELS, NUMERIC, RiskModel

MODEL = RiskModel()
FIELDS = NUMERIC + ["channel"]


def check(tx, context):
    if tx.channel not in CHANNELS:
        context.abort(grpc.StatusCode.INVALID_ARGUMENT, f"unknown channel {tx.channel!r}")
    if not 0 <= tx.hour <= 23:
        context.abort(grpc.StatusCode.INVALID_ARGUMENT, "hour must be between 0 and 23")
    if tx.amount <= 0:
        context.abort(grpc.StatusCode.INVALID_ARGUMENT, "amount must be positive")


def predictions(txs):
    rows = [{f: getattr(t, f) for f in FIELDS} for t in txs]
    return [risk_pb2.Prediction(score=s, decision=MODEL.decision(s), model_version=MODEL.version)
            for s in MODEL.scores(rows)]


class RiskScorer(risk_pb2_grpc.RiskScorerServicer):
    def Score(self, request, context):
        check(request, context)
        return predictions([request])[0]

    def ScoreBatch(self, request, context):
        if not 1 <= len(request.transactions) <= 256:
            context.abort(grpc.StatusCode.INVALID_ARGUMENT, "send between 1 and 256 transactions")
        for tx in request.transactions:
            check(tx, context)
        return risk_pb2.PredictionBatch(predictions=predictions(request.transactions),
                                        model_version=MODEL.version)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=8))
    risk_pb2_grpc.add_RiskScorerServicer_to_server(RiskScorer(), server)
    server.add_insecure_port("127.0.0.1:50051")      # local only: use TLS credentials anywhere else
    server.start()
    print(f"serving {MODEL.version} over gRPC on 127.0.0.1:50051", flush=True)
    server.wait_for_termination()


if __name__ == "__main__":
    serve()

"""The HTTP model server for the container: the same contract as the module 2 server,
but onnxruntime instead of scikit-learn, so the image needs no training libraries."""
import logging
from contextlib import asynccontextmanager
from typing import Literal

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, ConfigDict, Field

from onnx_model import RiskModel

log = logging.getLogger("risk")
logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
STATE = {"model": None}


class Transaction(BaseModel):
    model_config = ConfigDict(extra="forbid")
    amount: float = Field(gt=0, le=50_000)
    hour: int = Field(ge=0, le=23)
    channel: Literal["web", "app", "pos"]
    account_age_days: int = Field(ge=0, le=36_500)
    tx_last_24h: int = Field(ge=0, le=1_000)
    distance_km: float = Field(ge=0, le=20_000)


@asynccontextmanager
async def lifespan(app: FastAPI):
    model = RiskModel()
    warm = {"amount": 42.5, "hour": 14, "channel": "app", "account_age_days": 400,
            "tx_last_24h": 1, "distance_km": 3.0}
    for _ in range(5):
        model.scores([warm])                 # warm up before declaring readiness
    STATE["model"] = model
    log.info("ready: %s (risk.onnx sha256 %s...)", model.version, model.sha256[:12])
    yield
    STATE["model"] = None


app = FastAPI(title="Transaction risk (ONNX)", lifespan=lifespan)


@app.get("/health/live")
def live():
    return {"status": "alive"}


@app.get("/health/ready")
def ready():
    if STATE["model"] is None:
        raise HTTPException(status_code=503, detail="model not loaded yet")
    return {"status": "ready", "model_version": STATE["model"].version}


@app.post("/v1/predict")
def predict(tx: Transaction):
    model = STATE["model"]
    score = float(model.scores([tx.model_dump()])[0])
    return {"score": round(score, 6), "decision": model.decision(score), "model_version": model.version}
